/** user-defined types **/

/**
 * G per direction.
 */
export type AccelView = { forward: number; backward: number; left: number; right: number; up: number; down: number }
export type Activity = { 
/**
 * The top line: what you are doing.
 */
details?: string | null; 
/**
 * The second line: where.
 */
state?: string | null; timestamps?: Timestamps | null; assets?: Assets | null; buttons: Button[] }
/**
 * What kind of work an activity is — inline surfaces filter on it.
 */
export type ActivityKind = 
/**
 * svc-data load waterfall (snapshot load, parse, cook).
 */
"data-load" | 
/**
 * mod-langpatch: pack download, re-patch, waiting for SC to exit.
 */
"langpatch" | 
/**
 * svc-dossier owned-blueprints fetch.
 */
"blueprints" | 
/**
 * svc-dossier inventory fetch (stashes, entitlements, loadouts).
 */
"inventory" | 
/**
 * mod-devtracker: the first fill of the staff feed (svc-spectrum).
 */
"devtracker" | 
/**
 * svc-patchnotes: reading RSI's patch-note pages.
 */
"patch-notes" | 
/**
 * svc-commlinks: reading RSI's comm-link listing.
 */
"comm-links" | 
/**
 * svc-shipstore: the first fill of the store's ship pictures.
 */
"ship-store" | 
/**
 * svc-uex: the first fill of UEX's price lists.
 */
"uex" | 
/**
 * svc-dossier standing read for Contracts (reputation, completed
 * contracts).
 */
"standing"
/**
 * Where an activity is. `stage` is a user-facing label ("Parsing
 * DataCore…"); work without stages leaves it empty.
 */
export type ActivityPhase = { type: "running"; stage: string | null } | 
/**
 * Blocked on a condition outside the app, not on progress.
 */
{ type: "waiting"; reason: string }
export type ActivityRecord = { id: number; kind: ActivityKind; 
/**
 * Lowercase channel key the work is about ("live"), if any.
 */
channel: string | null; title: string; phase: ActivityPhase; 
/**
 * Epoch milliseconds as f64 (the `NotificationRecord` convention).
 */
started: number }
export type AppError = 
/**
 * Something the user can fix in Settings (missing server URL, …).
 */
{ kind: "Config"; message: string } | 
/**
 * Auth / token problems (keyring access, bad callback, …).
 */
{ kind: "Auth"; message: string } | 
/**
 * Everything else — bugs and IO surprises.
 */
{ kind: "Internal"; message: string }
/**
 * App-global preferences surfaced to the Settings page.
 * 
 * `#[serde(default)]` keeps old settings files loading after new fields are
 * added — never rename or repurpose a field, add a new one.
 */
export type AppSettings = { 
/**
 * Whether the first-launch onboarding has been completed/skipped.
 */
onboarding_completed: boolean; 
/**
 * Launch hidden to tray (companion mode). Also forced by `--minimized`,
 * which autostart passes.
 */
start_minimized: boolean; 
/**
 * Closing the main window hides to tray instead of quitting.
 */
close_to_tray: boolean; 
/**
 * Minimizing the main window hides it to tray instead of the taskbar.
 * Default off — taskbar minimize is the common expectation; tray purists
 * opt in.
 */
minimize_to_tray: boolean; 
/**
 * Run at login (delegated to the autostart plugin on update).
 */
autostart: boolean; 
/**
 * Starlume server base URL. `None` → all online features disabled.
 * A default ships once the server exists.
 */
server_url: string | null; 
/**
 * Feature modules the user enabled in onboarding/settings. Module ids
 * not in this list stay invisible in the UI.
 */
enabled_modules: string[]; 
/**
 * Master online switch (default ON). Off → no Discord auth, no RSI
 * fetch, no unofficial API — no network calls except **update checks**
 * (the one documented exception; see CLAUDE.md). Enforced via
 * [`AppState::require_online`](crate::AppState).
 */
online_enabled: boolean; 
/**
 * Master switch for **unofficial API** calls — the ToS-grey surface
 * (default OFF, opt-in): CIG's game-services gRPC backend and RSI's
 * Spectrum REST API, any RSI/CIG API Starlume is not an official client
 * of. Named for gRPC, its first member; the meaning widened when
 * Spectrum joined (2026-10), the name stays (settings rule: never
 * rename). Preserved but inert while `online_enabled` is off. Enforced
 * via `AppState::require_unofficial`.
 */
grpc_enabled: boolean; 
/**
 * One-time ToS acknowledgement — set automatically the first time
 * `grpc_enabled` flips on (the UI shows the consent dialog before that).
 * Covers every unofficial API, like `grpc_enabled`.
 */
grpc_consented: boolean; 
/**
 * Per-feature allow-list for unofficial API calls (ids from
 * [`GRPC_FEATURES`] — gRPC and Spectrum features alike, despite the
 * name), so users can enable e.g. blueprints but not the dev tracker. A
 * feature is live only when `online_enabled` + `grpc_enabled` +
 * membership here all hold.
 */
grpc_features: string[]; 
/**
 * Show native OS toasts for notifications raised while the window is
 * hidden/minimized (companion mode). Default ON — a hidden tray app has
 * no other way to reach the user.
 */
native_notifications: boolean; 
/**
 * Warm the game-data cache in the background at app start (scan installs,
 * cook the newest PU build if its snapshot is missing/stale). Default ON —
 * catalogs are instantly browsable instead of gated on a manual Load.
 * Local file reads only, no online implications; the heavy parse runs at
 * most once per game patch.
 */
auto_load_game_data: boolean; 
/**
 * Fetch the owned-blueprint set from CIG's backend at app start (gated
 * by the `blueprints` gRPC feature — inert unless online + gRPC + that
 * feature are all on). Default ON: the Hearth-style automation the owned
 * catalog/text marking rides on.
 */
blueprints_auto_fetch?: boolean; 
/**
 * When the owned-blueprint set changes, re-apply text patching for
 * owned installs so the in-game mission text re-renders ownership.
 * Default ON; honors all the langpatch write-gates.
 */
blueprints_auto_langpatch?: boolean; 
/**
 * Build archive: how many releases (newest first) keep an archived
 * game-data build after a patch replaces it. Default 3 — the raw
 * extract (~35 MB) per kept build, the input for patch diffs.
 */
archive_releases: number; 
/**
 * Keep every build within a kept release (PTU waves, hotfixes), not
 * only its newest one. Default off — a power-user option.
 */
archive_all_builds: boolean; 
/**
 * Archive PTU / Tech Preview builds too. Default off: Live/Hotfix only.
 */
archive_test_channels: boolean; 
/**
 * The Home page layout: the cards the user arranged, in order, each
 * shown or hidden. Ids are `<owner>:<card>` (`shell:game-status`,
 * `items:summary`). Empty = the default layout. Cards not listed — a
 * module enabled later — follow the listed ones at their default
 * visibility; listed ids no longer available are skipped, not dropped,
 * so re-enabling a module restores its placement.
 */
home_cards: HomeCardPref[]; 
/**
 * Modules the user has been offered: shown in onboarding or on a
 * What's-new page. A module this build offers that is missing here
 * gets a What's-new page and a startup notification, once
 * (`modules::not_yet_offered`). `None` = an install from before the
 * guide existed; [`AppSettings::load`] seeds it.
 */
modules_offered: string[] | null; 
/**
 * The newest release whose What's-new changes the user has seen (a
 * version like "0.2.0"; the changes are authored in
 * `src/lib/guides.ts`). `None` is seeded like `modules_offered`.
 */
guide_seen: string | null; 
/**
 * Draw the fitted ship in 3D on Build. Off, Build shows its picture and
 * reads no models.
 */
ship_holo?: boolean; 
/**
 * Read the running game's local telemetry stream (vehicle, vitals,
 * events, the aUEC balance) from `127.0.0.1`. Default OFF, opt-in.
 * Loopback, not an outbound call: **not** behind `online_enabled` or the
 * unofficial-API switches, and unaffected by them (see CLAUDE.md).
 * Turning it on starts the reader (`telemetry::sync`) and makes
 * `launcher_open` start the launcher with the variable the game needs;
 * the permanent variable install is its own explicit action.
 */
telemetry_enabled: boolean; 
/**
 * Follow the game's `Game.log` for what happens in a session (shard,
 * location, missions, purchases, refinery orders). Default OFF, opt-in
 * (as Hearth's log sensor was). A local file read, not a network call:
 * **not** behind `online_enabled`. Turning it on starts the watcher
 * (`gamelog::sync`); off, no log is statted or read.
 */
gamelog_enabled: boolean; 
/**
 * Keep a capture of every session (Session Log): all its telemetry
 * frames and its Game.log, compressed, beside the session's file
 * (`capture.rs`). Default OFF. About 3 MB an hour.
 */
session_capture: boolean; 
/**
 * The most all captures may take together, in MB; the oldest go
 * first. Default 500.
 */
session_capture_budget_mb?: number; 
/**
 * Discord Rich Presence (Settings › Discord). Sends what you are doing
 * to the Discord app, which publishes it: a network call, so it also
 * needs `online_enabled`. Off by default.
 */
presence: PresenceSettings }
